import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'

type Post = {
  id: number
  title: string
  body: string
  userId: number
}

type Comment = {
  id: number
  name: string
  body: string
  email: string
  postId: number
}

type PageProps = {
  params: Promise<{ id: string }>
}

export const dynamicParams = true
export const revalidate = 300

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts').then((res) =>
    res.json()
  )

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params

  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    }).then((res) => res.json())

    if (!post || !post.id) {
      return {
        title: 'Post Not Found',
      }
    }

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch {
    return {
      title: 'Post Not Found',
    }
  }
}

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] }> {
  const [postRes, commentsRes] = await Promise.all([
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    }),
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
      next: { revalidate: 300 },
    }),
  ])

  if (!postRes.ok) {
    notFound()
  }

  const post: Post = await postRes.json()
  const comments: Comment[] = await commentsRes.json()

  if (!post || !post.id) {
    notFound()
  }

  return { post, comments }
}

export default async function BlogPost({ params }: PageProps) {
  const { id } = await params
  const { post, comments } = await getPostData(id)

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

