import { NextResponse } from 'next/server'

type Post = {
  id: number
  title: string
  content: string
  createdAt?: string
}

type CreatePostBody = {
  title?: string
  content?: string
}

const posts: Post[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

export async function GET() {
  return NextResponse.json(posts, { status: 200 })
}

export async function POST(request: Request) {
  const body: CreatePostBody = await request.json()
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json({ error: 'Title and content are required' }, { status: 400 })
  }

  const newPost: Post = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'

type Params = {
  params: Promise<{ id: string }>
}

type UpdatePostBody = {
  title?: string
  content?: string
}

type PostResponse = {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
  message?: string
}

export async function GET(_request: Request, { params }: Params) {
  const { id } = await params
  const post: PostResponse = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(request: Request, { params }: Params) {
  const { id } = await params
  const body: UpdatePostBody = await request.json()
  const { title, content } = body

  const updatedPost: PostResponse = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(_request: Request, { params }: Params) {
  const { id } = await params

  return NextResponse.json({ message: `Post ${id} deleted successfully` }, { status: 200 })
}

